import { useState, type ReactNode } from 'react'
import type { RunDetail, RunInputs, RunInputWorker, RunScope, WorkerResult } from '../api.ts'
import { CreatedFiles } from '../CreatedFiles.tsx'
import { AppLink, ErrorPanel, LoadingPanel } from '../panels.tsx'
import { NodeSection } from '../SectionIndex.tsx'
import type { Resource } from '../useResource.ts'
import { LaunchReceipt, StopLine, TaskPanel, WorkerQuestions, WorkerSignals } from '../WorkerInputs.tsx'
import { filesCount } from './model.ts'
import type { CheckTarget } from './Requirements.tsx'
import { ResultError, ResultFacts, WorkerNarrative } from './ResultFacts.tsx'
import './worker.css'

type SnapshotNode = RunDetail['snapshot']['nodes'][number]

/** The pinned task behind a disclosure, closed by default and opened when a finding link hands over a quote to highlight. */
function TaskDisclosure({ highlight, children }: { highlight: string | null; children: ReactNode }) {
  const [open, setOpen] = useState(highlight !== null)
  return (
    <details className="evidence-section task-details" data-testid="task-details" open={open} onToggle={event => setOpen(event.currentTarget.open)}>
      <summary id="task-details-summary">Task: what this worker was asked to do</summary>
      {children}
    </details>
  )
}

/**
 * Where the worker's result stands with its verification (docs/PRD_VIEWER_UX.md 8): the revision frozen at handoff, then
 * "verified" only when the verification passed on this result; a failed or unfinished one says so, since the facts and the
 * gate's error it links are shown once, on the verify node.
 */
function VerifiedLine({ result, checksNode, frozenCommit, repairNote, onNavigate }: {
  result: WorkerResult
  checksNode: NonNullable<Props['checksNode']>
  frozenCommit: string | null
  repairNote: string
  onNavigate: (pathname: string) => void
}) {
  const passed = checksNode.status === 'succeeded' && result.status === 'succeeded' && result.error === null
  const failed = !passed && (checksNode.status === 'failed' || result.error !== null || result.status === 'failed')
  const state = passed ? 'verified' : failed ? 'failed' : 'unverified'
  const after = repairNote ? ` ${repairNote}` : ''
  const words = passed ? `verified on attempt ${result.attempt}${after}`
    : failed ? `verification failed on attempt ${result.attempt}${after}`
      : checksNode.status === 'pending' || checksNode.attempt === 0 ? 'not verified yet'
        : `verification attempt ${checksNode.attempt} is ${checksNode.status === 'running' ? 'running' : 'not finished'}`
  const repaired = passed && result.output_commit !== null && frozenCommit !== null && result.output_commit !== frozenCommit
  return (
    <p className="worker-verified" data-testid="worker-verified" data-state={state}>
      {frozenCommit ? <>Frozen at handoff as <code>{frozenCommit.slice(0, 7)}</code>; {words}</> : `${words[0].toUpperCase()}${words.slice(1)}`}
      {repaired && <> as <code>{result.output_commit!.slice(0, 7)}</code></>} ·{' '}
      <AppLink href={checksNode.href} onNavigate={onNavigate}>{failed ? 'the gate\'s reasons' : 'facts and checks'} on {checksNode.label} ›</AppLink>
    </p>
  )
}

type Props = {
  scope: RunScope
  /** The node's result as loaded, with its loading, error and absence lines already worded. */
  renderResult: (evidence: (data: WorkerResult) => ReactNode) => ReactNode
  result: Resource<WorkerResult>
  /** Whether this node shows the result's facts (no verify node links the same result) and the worker's narrative. */
  role: { facts: boolean; narrative: boolean }
  /** The verify node that shows the result's facts and executed checks, with its status; null when the pinned graph has none. */
  checksNode: (CheckTarget & { status: SnapshotNode['status']; attempt: number }) | null
  /** The revision the worker handed over (the verification's first attempt's output commit); null until known. */
  frozenCommit: string | null
  /** "after operator repair 1" when the verify node's latest attempt followed a repair; empty otherwise. */
  repairNote: string
  inputs: Resource<RunInputs | null>
  onRetryInputs: () => void
  worker: RunInputWorker | null
  reviewNode: SnapshotNode | null
  refreshToken: number
  onNavigate: (pathname: string) => void
  highlight: string | null
  onHighlightApplied: () => void
  fileFocus: string | null
  onFileFocusApplied: () => void
}

/**
 * A launch node's sections (docs/PRD_VIEWER_UX.md 4.5): the questions to the operator while there are any, what the worker
 * produced (its narrative, and the result's facts unless the verify node shows them) and the files it created or changed
 * as captured at freeze, then its completion signal, the launch receipt and the task behind a disclosure.
 */
export function WorkerSections({ scope, renderResult, result, role, checksNode, frozenCommit, repairNote, inputs, onRetryInputs, worker, reviewNode, refreshToken, onNavigate, highlight, onHighlightApplied, fileFocus, onFileFocusApplied }: Props) {
  const recordedInputs = inputs.status === 'ready' ? inputs.data : null
  const files = result.status === 'ready' ? filesCount(result.data) : 0
  return (
    <>
      {worker !== null && worker.questions.length > 0 && (
        <NodeSection sectionKey="questions" labelledBy="worker-questions-title">
          <WorkerQuestions questions={worker.questions} />
        </NodeSection>
      )}

      <NodeSection sectionKey="result" title="Result">
        {renderResult(data => (
          <div className="worker-evidence" data-testid="worker-result" data-view="produced">
            {!role.facts && checksNode !== null && <VerifiedLine result={data} checksNode={checksNode} frozenCommit={frozenCommit} repairNote={repairNote} onNavigate={onNavigate} />}
            {role.narrative && <WorkerNarrative result={data} />}
            {role.facts && <><ResultFacts result={data} /><ResultError result={data} /></>}
          </div>
        ))}
      </NodeSection>

      {result.status === 'ready' && files > 0 && (
        <NodeSection sectionKey="files" labelledBy="evidence-created-files">
          <CreatedFiles scope={scope} result={result.data} reviewNode={reviewNode} refreshToken={refreshToken} focusPath={fileFocus} onFocusApplied={onFileFocusApplied} />
        </NodeSection>
      )}

      {(inputs.status === 'loading' || inputs.status === 'idle') && <LoadingPanel>Loading the run inputs…</LoadingPanel>}
      {inputs.status === 'error' && <ErrorPanel error={inputs.error} what="The run inputs" onRetry={onRetryInputs} />}
      {inputs.status === 'ready' && recordedInputs === null && (
        <p className="projects-muted" data-testid="worker-inputs-none">
          Inputs not recorded for this run (the export predates run inputs; re-export it with the workflow CLI), so the task, launch receipt and completion signal cannot be shown.
        </p>
      )}
      {recordedInputs !== null && worker === null && (
        <p className="projects-muted" data-testid="worker-inputs-unmatched">The run inputs list no worker launched by this node.</p>
      )}
      {worker !== null && (
        <>
          <NodeSection sectionKey="report" labelledBy="worker-completion-title">
            <WorkerSignals completion={worker.completion} handoff={worker.handoff} worker={worker} result={result} checksNode={checksNode} onNavigate={onNavigate} />
          </NodeSection>
          <NodeSection sectionKey="session" labelledBy="launch-receipt-title">
            <LaunchReceipt launch={worker.launch} />
            {worker.questions.length === 0 && <p className="projects-muted" data-testid="worker-questions-none">No questions were recorded for this worker.</p>}
            <StopLine stop={worker.stop} />
          </NodeSection>
          <NodeSection sectionKey="task" labelledBy="task-details-summary">
            <TaskDisclosure highlight={highlight}>
              <TaskPanel worker={worker} result={result} highlight={highlight} onHighlightApplied={onHighlightApplied} checksNode={checksNode} onNavigate={onNavigate} />
            </TaskDisclosure>
          </NodeSection>
        </>
      )}
    </>
  )
}
/* ---- Launch node sections (docs/PRD_VIEWER_UX.md 4.5) ---- */

.worker-verified { margin: 0 0 8px; font-size: 0.9rem; }

import { useCallback, useMemo, useState, type ReactNode } from 'react'
import { attemptResultUris, type Now, type Timeline } from '../../contracts/projects/triage.ts'
import { scopedResultPath, type RunDetail, type RunInputs, type ReviewResult, type RunScope, type WorkerResult, type WorkflowEvent } from './api.ts'
import { ChallengeSections } from './node/ChallengeSections.tsx'
import { AwaitingNotice, ControllerSections } from './node/ControllerSections.tsx'
import { attemptStrip, causeOf, nodeTiming, resultRole, revisionAttempt, verifiedSections, workerSectionEntries, type SectionEntry } from './node/model.ts'
import { ReviewSections } from './node/ReviewSections.tsx'
import { CandidateLanes, VerifiedEvidence, WorkerReportLink, type LaneEntry } from './node/VerifySections.tsx'
import { WorkerSections } from './node/WorkerSections.tsx'
import { NodeHeader } from './NodeHeader.tsx'
import { AppLink, ErrorPanel, LoadingPanel, StatusBadge } from './panels.tsx'
import { attemptPathname, runPathname } from './routes.ts'
import { NodeSection, SectionIndex } from './SectionIndex.tsx'
import { isChallengeNode } from './status.ts'
import { Time } from './Time.tsx'
import type { Resource } from './useResource.ts'
import { useRunResult, useRunResults } from './useRunData.ts'
import './node.css'

type DefinitionNode = RunDetail['definition']['nodes'][number]
type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type ReviewTransport = ReviewResult['reviewer']['transport']

type Props = {
  scope: RunScope
  detail: RunDetail
  definition: DefinitionNode
  node: SnapshotNode
  /** The attempt the path names (`/attempts/<k>`); null shows the latest. */
  attempt: number | null
  events: Resource<WorkflowEvent[]>
  onRetryEvents: () => void
  /** The run's inputs (null once loaded when the export predates them), shared by every node of the run. */
  inputs: Resource<RunInputs | null>
  onRetryInputs: () => void
  /** The run's timeline, once its events loaded: the header's times, attempts and markers. */
  timeline: Timeline | null
  /** The run's situation, once derived: its next step is repeated on the focus node. */
  now: Now | null
  clock: number
  refreshToken: number
  onNavigate: (pathname: string) => void
  /** A requirement quote to highlight in this node's task, handed over by a review finding link. */
  highlight: string | null
  onHighlightApplied: () => void
  onOpenRequirement: (nodeId: string, quote: string) => void
  /** A captured file to scroll to on this launch node, handed over by a review finding's file link. */
  fileFocus: string | null
  onFileFocusApplied: () => void
  onOpenFile: (nodeId: string, path: string) => void
}

/**
 * One node of a run (docs/PRD_VIEWER_UX.md 4.4-4.9): the header (status by cause, timing, attempts, next step), a section
 * index with counts, then the sections of its kind (worker, verification, candidate, review, challenge or the controller's
 * own steps) and History, always last. Empty sections are absent; a result the launch and verify nodes share is said once.
 * An earlier attempt's page shows that attempt's own result under a banner that leads back to the latest.
 */
export function NodeDetail({ scope, detail, definition, node, attempt, events, onRetryEvents, inputs, onRetryInputs, timeline, now, clock, refreshToken, onNavigate, highlight, onHighlightApplied, onOpenRequirement, fileFocus, onFileFocusApplied, onOpenFile }: Props) {
  const definitionNodes = detail.definition.nodes
  const snapshotNodes = detail.snapshot.nodes
  // A review's executor wording depends on the transport its served result records, known once the review panel loads it.
  const [reviewTransport, setReviewTransport] = useState<ReviewTransport | undefined>(undefined)

  const isWorker = definition.kind === 'worker'
  const isChallenge = isChallengeNode(definition)
  const isReview = definition.kind === 'review' && !isChallenge
  const isCandidate = node.node_id === 'candidate'
  const isVerify = definition.kind === 'verification' && !isCandidate
  const isController = definition.kind === 'prepare' || definition.kind === 'integration'
  const latest = node.attempt
  const isLatest = attempt === null || attempt === latest
  const shownAttempt = attempt ?? latest
  const recorded = shownAttempt >= 1 && shownAttempt <= latest

  // What this view reads: the latest attempt's result as served, or the viewed attempt's own (`results/<lane>/<k>`).
  const attemptUris = useMemo(() => attemptResultUris(detail, node.node_id), [detail, node.node_id])
  const resultUri = definition.kind === 'review' ? null
    : isLatest || !isVerify ? node.result_uri
      : attemptUris.find(item => item.attempt === attempt)?.uri ?? null
  const lanes: LaneEntry[] = isLatest || !isCandidate ? node.lane_results
    : attemptUris.filter(item => item.attempt === attempt).map(item => ({ worker: item.lane, attempt: item.attempt, result_uri: item.uri }))
  const resultPath = resultUri === null ? null : scopedResultPath(scope, resultUri)
  const stamp = String(refreshToken)
  const { state: result, reload: reloadResult } = useRunResult(scope, resultPath, stamp)
  const resultData = result.status === 'ready' ? result.data : null

  // The attempt strip: a chip shows once one of its results loaded (read through the run's cache, asked again on new events).
  const strip = useMemo(() => (timeline ? attemptStrip(detail, timeline, node.node_id) : []), [detail, timeline, node.node_id])
  const chipUris = useMemo(() => strip.flatMap(item => (item.kind === 'attempt' ? item.chip.uris : [])), [strip])
  const { results: chipResults } = useRunResults(scope, chipUris, `${refreshToken}:${detail.snapshot.last_sequence}`)
  const loaded = useCallback((uri: string) => chipResults.has(uri), [chipResults])
  const viewedChip = strip.flatMap(item => (item.kind === 'attempt' && item.chip.attempt === shownAttempt ? [item.chip] : []))[0]

  // The candidate's own verdict is its lanes': a failing lane's gate reasons are the cause its header names.
  const { results: laneResults } = useRunResults(scope, useMemo(() => lanes.map(entry => entry.result_uri), [lanes]), stamp)
  const failure = lanes.flatMap(entry => {
    const error = laneResults.get(entry.result_uri)?.error
    return error ? [`${entry.worker}: ${error.message}`] : []
  }).join('; ') || null

  const nodeEvents = events.status === 'ready' ? events.data.filter(event => event.node_id === node.node_id) : []
  const reuse = nodeEvents.filter(event => event.type === 'result_reused')
  const approvals = nodeEvents.filter(event => event.type === 'approval_requested')

  const recordedInputs = inputs.status === 'ready' ? inputs.data : null
  const worker = isWorker && recordedInputs !== null ? recordedInputs.workers.find(candidate => candidate.launch_node_id === node.node_id) ?? null : null
  // The design challenge is also of kind review; the independent review is the other one.
  const reviewNode = snapshotNodes.find(candidate => candidate.kind === 'review' && !isChallengeNode(candidate)) ?? null
  const hasNode = (nodeId: string) => definitionNodes.some(candidate => candidate.node_id === nodeId)
  const nodeLink = (nodeId: string) => ({ node_id: nodeId, href: runPathname(scope.projectId, scope.workflowId, scope.runId, nodeId), label: definitionNodes.find(candidate => candidate.node_id === nodeId)!.label })
  const launchNodeOf = (lane: string) => {
    const launched = recordedInputs?.workers.find(candidate => candidate.node_id === lane)?.launch_node_id
    const id = launched && hasNode(launched) ? launched : hasNode(`launch_${lane}`) ? `launch_${lane}` : null
    return id === null ? null : nodeLink(id)
  }
  const lane = isWorker ? worker?.node_id ?? node.node_id.replace(/^launch_/, '') : null
  const verifyId = lane !== null && hasNode(`verify_${lane}`) ? `verify_${lane}` : null
  const verifyState = verifyId === null ? null : snapshotNodes.find(candidate => candidate.node_id === verifyId) ?? null
  const verifyNode = verifyId === null ? null : { ...nodeLink(verifyId), status: verifyState?.status ?? 'pending' as const, attempt: verifyState?.attempt ?? 0 }
  // What the worker handed over: the verification's first attempt ran on the snapshot frozen at handoff (a repair makes a new one).
  const frozenUri = verifyId === null ? null : attemptResultUris(detail, verifyId).find(item => item.attempt === 1)?.uri ?? null
  const { results: frozenResults } = useRunResults(scope, useMemo(() => (frozenUri === null ? [] : [frozenUri]), [frozenUri]), stamp)
  const frozenCommit = frozenUri === null ? null : frozenResults.get(frozenUri)?.output_commit ?? null
  const role = resultRole(detail, node.node_id)
  const reportNode = isVerify && !role.narrative && role.partner !== null ? nodeLink(role.partner) : null
  const repairs = (timeline?.markers ?? []).filter(marker => marker.kind === 'repair' && verifyNode !== null && marker.node_id === verifyNode.node_id)
  const repairNote = repairs.length ? `after operator ${repairs.map(marker => `repair ${marker.repair?.n ?? ''}`.trim()).join(', ')}` : ''

  const timing = timeline && recorded ? nodeTiming(timeline, node.node_id, isLatest ? null : attempt, isVerify ? resultData : null) : null
  const headerStatus = isLatest ? node.status : viewedChip?.status ?? resultData?.status ?? 'pending'
  const cause = causeOf({
    timeline, nodeId: node.node_id, attempt: isLatest ? null : shownAttempt, events: nodeEvents, latest,
    error: headerStatus === 'failed' ? resultData?.error?.message ?? failure : null,
  })
  // A live or failed verification counts its attempts against the cap, which a repair restarts (5.3).
  const cap = recordedInputs?.max_verification_attempts ?? null
  const revision = (isVerify || isCandidate) && recorded && timeline !== null && cap !== null && (headerStatus === 'running' || headerStatus === 'failed')
    ? { attempt: revisionAttempt(timeline, node.node_id, shownAttempt), of: cap }
    : null
  const next = isLatest && now?.focus?.node_id === node.node_id && (now.next.steps.length > 0 || now.next.action === 'required') ? now.next : null
  const attemptHref = (value: number) => attemptPathname(scope.projectId, scope.workflowId, scope.runId, node.node_id, value)
  const nodeHref = runPathname(scope.projectId, scope.workflowId, scope.runId, node.node_id)

  const renderResult = (evidence: (data: WorkerResult) => ReactNode) => (
    <>
      {resultUri === null && lanes.length === 0 && <p className="projects-muted" data-testid="result-none">No result has been published for this node{node.attempt === 0 ? ' (it has not started)' : ''}.</p>}
      {resultUri !== null && resultPath === null && (
        <p className="projects-error-inline" role="alert" data-testid="result-unscoped">
          The result link <code>{resultUri}</code> is outside this run's results route and was not fetched.
        </p>
      )}
      {resultPath !== null && result.status === 'loading' && <LoadingPanel>Loading the result…</LoadingPanel>}
      {resultPath !== null && result.status === 'error' && <ErrorPanel error={result.error} what="The node result" onRetry={reloadResult} />}
      {resultPath !== null && result.status === 'ready' && evidence(result.data)}
    </>
  )

  // The section index: what the kind lists, only when it lists something, then reuse (only with reuse events) and History.
  const sections: SectionEntry[] = [
    ...(isWorker ? workerSectionEntries(worker, resultData) : []),
    ...(isCandidate && lanes.length > 0 ? [{ key: 'lanes', label: 'Lanes', count: lanes.length }] : []),
    ...((isVerify || isCandidate) && resultData !== null ? verifiedSections(resultData) : []),
    // A review or challenge that recorded nothing keeps only its honesty line, with no chip.
    ...(isReview && reviewTransport !== undefined ? [{ key: 'review', label: 'Review' }] : []),
    ...(isChallenge && recordedInputs?.challenge ? [{ key: 'challenge', label: 'Challenge' }] : []),
    ...(reuse.length > 0 ? [{ key: 'reuse', label: 'Reuse', count: reuse.length }] : []),
    { key: 'history', label: 'History', ...(events.status === 'ready' ? { count: nodeEvents.length } : {}) },
  ]
  // An earlier attempt keeps only a verification's own result; any other step's earlier attempt shows its times and History.
  const evidence = isLatest || (recorded && (isVerify || isCandidate))

  return (
    <section className="node-detail" aria-labelledby="node-detail-title" data-testid="node-detail" data-node-id={node.node_id} data-attempt={isLatest ? undefined : shownAttempt}>
      <NodeHeader
        definition={definition}
        status={headerStatus}
        attempt={shownAttempt}
        timing={timing}
        clock={clock}
        cause={cause}
        revision={revision}
        timeline={timeline}
        reviewTransport={reviewTransport}
        verifyNode={verifyNode}
        strip={strip}
        loaded={loaded}
        attemptHref={attemptHref}
        next={next}
        onNavigate={onNavigate}
      />

      {!isLatest && (
        <p className="projects-notice attempt-banner" role="note" data-testid="attempt-banner">
          {recorded ? `You are viewing attempt ${attempt} of ${latest}. ` : `Attempt ${attempt} of this step was not recorded. `}
          <AppLink href={nodeHref} onNavigate={onNavigate}>{latest === 0 ? 'Open the step ›' : `The latest is attempt ${latest} ›`}</AppLink>
        </p>
      )}

      {isLatest && node.status === 'awaiting_approval' && <AwaitingNotice approvals={approvals} />}

      {!isController && (isLatest || recorded) && (
        <SectionIndex label={definition.label} sections={evidence ? sections : sections.filter(section => section.key === 'history')}>
          {reportNode && <WorkerReportLink href={reportNode.href} label={reportNode.label} onNavigate={onNavigate} />}
        </SectionIndex>
      )}

      {!evidence && recorded && <p className="projects-muted" data-testid="attempt-latest-only">Only the latest attempt's evidence is kept for this step; the times above are this attempt's.</p>}

      {evidence && (
        isWorker ? (
          <WorkerSections
            scope={scope}
            renderResult={renderResult}
            result={result}
            role={role}
            checksNode={verifyNode}
            frozenCommit={frozenCommit}
            repairNote={repairNote}
            inputs={inputs}
            onRetryInputs={onRetryInputs}
            worker={worker}
            reviewNode={reviewNode}
            refreshToken={refreshToken}
            onNavigate={onNavigate}
            highlight={highlight}
            onHighlightApplied={onHighlightApplied}
            fileFocus={fileFocus}
            onFileFocusApplied={onFileFocusApplied}
          />
        ) : isChallenge ? (
          <ChallengeSections inputs={inputs} onRetryInputs={onRetryInputs} />
        ) : isReview ? (
          <ReviewSections
            scope={scope}
            node={node}
            definitionNodes={definitionNodes}
            snapshotNodes={snapshotNodes}
            inputs={inputs}
            refreshToken={refreshToken}
            onNavigate={onNavigate}
            onOpenRequirement={onOpenRequirement}
            onOpenFile={onOpenFile}
            onTransport={setReviewTransport}
          />
        ) : isController ? (
          <ControllerSections scope={scope} renderResult={renderResult} />
        ) : (
          <>
            {lanes.length > 0 && <CandidateLanes scope={scope} lanes={lanes} launchNodeOf={launchNodeOf} stamp={stamp} onNavigate={onNavigate} />}
            {renderResult(data => <VerifiedEvidence scope={scope} result={data} phase="worker" anchored />)}
          </>
        )
      )}

      {reuse.length > 0 && (
        <NodeSection sectionKey="reuse" title="Reuse evidence">
          <ul className="evidence-list" data-testid="reuse-list">
            {reuse.map(event => (
              <li key={event.event_id}>
                Attempt {event.attempt} reused the result of attempt {event.reused_from_attempt ?? 'unknown'} (event {event.sequence}, <Time iso={event.occurred_at} seconds />): {event.message}
              </li>
            ))}
          </ul>
        </NodeSection>
      )}

      <NodeSection sectionKey="history" title="History">
        {events.status === 'loading' && <LoadingPanel>Loading events…</LoadingPanel>}
        {events.status === 'error' && <ErrorPanel error={events.error} what="The run events" onRetry={onRetryEvents} />}
        {events.status === 'ready' && (nodeEvents.length === 0 ? (
          <p className="projects-muted" data-testid="events-none">No events reference this node.</p>
        ) : (
          <ol className="event-list" data-testid="node-events">
            {nodeEvents.map(event => (
              <li key={event.event_id} data-attempt={event.attempt}>
                <span className="event-seq">#{event.sequence}</span> <span className="projects-muted"><Time iso={event.occurred_at} seconds /></span>{' '}
                <span className="event-type">{event.type.replace(/_/g, ' ')}</span>
                {event.status && <> · <StatusBadge status={event.status} /></>}
                {event.attempt > 0 && <> · attempt {event.attempt}</>}
                {event.message && <> — {event.message}</>}
                {event.artifact && <> · artifact <code>{event.artifact.artifact_id}</code> ({event.artifact.kind})</>}
              </li>
            ))}
          </ol>
        ))}
      </NodeSection>
    </section>
  )
}

import { useCallback, useEffect, useRef, useState, type RefObject } from 'react'
import { Markdown } from '../document/Markdown.tsx'
import {
  fetchArtifactText,
  fetchReviewResult,
  NOT_RECORDED,
  orNotRecorded,
  paths,
  scopedReviewPath,
  type ReviewFinding,
  type RunDetail,
  type RunScope,
  type WorkerResult,
} from './api.ts'
import { capturedFiles, fileAnchorId, isMarkdownPath, NOT_CAPTURED_WORDING, notCapturedFiles, recordsCapture, type CapturedFile } from './files.ts'
import { findingsForFile, linesNamed } from './findings.ts'
import { ErrorPanel, LoadingPanel } from './panels.tsx'
import { keepInView } from './scroll.ts'
import { useResource, type Resource } from './useResource.ts'

type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type Range = [number, number]

type Props = {
  scope: RunScope
  result: WorkerResult
  /** The run's review node, whose recorded findings are shown on the files they name; null when the graph has none. */
  reviewNode: SnapshotNode | null
  refreshToken: number
  /** A captured file to scroll to, handed over by a review finding's file link; null otherwise. */
  focusPath: string | null
  onFocusApplied: () => void
}

/** The review a finding list comes from, the same way the review node finds it; null when none is recorded. */
function reviewPathOf(scope: RunScope, node: SnapshotNode | null): string | null {
  if (node === null) return null
  if (node.result_uri !== null) return scopedReviewPath(scope, node.result_uri)
  return node.status === 'pending' ? null : paths.review(scope, Math.max(node.attempt, 1))
}

function rangeText([from, to]: Range): string {
  return from === to ? `line ${from}` : `lines ${from}–${to}`
}

/** The review findings that name this file: severity, reviewer, disposition and message, and a control to mark the lines a finding names. */
function FileFindings({ findings, path, onShowLines }: { findings: Resource<ReviewFinding[] | null>; path: string; onShowLines: (ranges: Range[]) => void }) {
  if (findings.status === 'idle') return <p className="projects-muted" data-testid="file-findings-no-review">No review is recorded for this run, so no findings are shown on its files.</p>
  if (findings.status === 'loading') return <LoadingPanel>Loading the review findings…</LoadingPanel>
  if (findings.status === 'error') return <p className="projects-error-inline" role="alert">The recorded review could not be loaded, so findings on this file are not shown.</p>
  if (findings.data === null) return <p className="projects-muted" data-testid="file-findings-no-review">No review is recorded for this run, so no findings are shown on its files.</p>
  const named = findingsForFile(findings.data, path)
  if (named.length === 0) return <p className="projects-muted" data-testid="file-findings-none">No review finding names this file.</p>
  return (
    <ul className="evidence-list" data-testid="file-findings">
      {named.map((finding, index) => {
        const ranges = linesNamed(finding.message, path)
        return (
          <li key={index} data-testid="file-finding" data-severity={finding.severity} data-reviewer={finding.reviewer} data-disposition={finding.disposition}>
            <span className="finding-severity">{finding.severity}</span>
            {' '}· <span data-testid="file-finding-reviewer">{finding.reviewer}</span> · {finding.disposition} — {finding.message}
            {ranges.length > 0 && (
              <>
                {' '}
                <button type="button" className="button button-small" data-testid="show-lines" onClick={() => onShowLines(ranges)}>
                  Show {ranges.map(rangeText).join(', ')}
                </button>
              </>
            )}
          </li>
        )
      })}
    </ul>
  )
}

/** The exact file content, one element per line; lines a finding names are marked. */
function FileSource({ text, marked, preRef }: { text: string; marked: Range[]; preRef: RefObject<HTMLPreElement | null> }) {
  const lines = text.endsWith('\n') ? text.slice(0, -1).split('\n') : text.split('\n')
  const isMarked = (line: number) => marked.some(([from, to]) => line >= from && line <= to)
  return (
    <pre className="artifact-log" data-testid="file-source" tabIndex={0} ref={preRef}>
      {lines.map((line, index) => {
        const number = index + 1
        return isMarked(number)
          ? <mark key={number} data-line={number} data-finding-line="true">{line}{'\n'}</mark>
          : <span key={number} data-line={number}>{line}{'\n'}</span>
      })}
    </pre>
  )
}

/**
 * One captured file: the findings that name it, then its content. Markdown is rendered inline with a Source view; any other
 * text is shown as source on demand. "Show lines" switches to the source, the only view where line numbers mean anything.
 */
function CapturedFilePanel({ scope, file, findings, focused }: { scope: RunScope; file: CapturedFile; findings: Resource<ReviewFinding[] | null>; focused: boolean }) {
  const markdown = isMarkdownPath(file.path)
  const [view, setView] = useState<'rendered' | 'source' | 'closed'>(markdown ? 'rendered' : 'closed')
  const [marked, setMarked] = useState<Range[]>([])
  const [scrollRequest, setScrollRequest] = useState(0)
  const preRef = useRef<HTMLPreElement>(null)
  const panelRef = useRef<HTMLElement>(null)
  const headingRef = useRef<HTMLHeadingElement>(null)
  const load = useCallback((signal: AbortSignal) => fetchArtifactText(scope, file.artifact_id, signal), [scope, file.artifact_id])
  const { state, reload } = useResource(view === 'closed' ? null : `file:${file.artifact_id}`, load)

  useEffect(() => {
    if (!focused || !headingRef.current) return
    panelRef.current?.focus({ preventScroll: true })
    return keepInView(headingRef.current, { block: 'start' })
  }, [focused])
  useEffect(() => {
    if (scrollRequest === 0 || state.status !== 'ready') return
    preRef.current?.querySelector('[data-finding-line]')?.scrollIntoView({ block: 'center' })
  }, [scrollRequest, state.status])

  const showLines = (ranges: Range[]) => {
    setMarked(ranges)
    setView('source')
    setScrollRequest(previous => previous + 1)
  }
  const headingId = `${fileAnchorId(file.path)}-title`
  return (
    <section
      ref={panelRef}
      id={fileAnchorId(file.path)}
      tabIndex={-1}
      className="captured-file"
      aria-labelledby={headingId}
      data-testid="captured-file"
      data-path={file.path}
      data-view={view}
    >
      <h5 id={headingId} ref={headingRef}><code>{file.path}</code> <span className="projects-muted">· captured at freeze · sha256 {file.sha256.slice(0, 12)}…</span></h5>
      <h6>Findings on this file</h6>
      <FileFindings findings={findings} path={file.path} onShowLines={showLines} />
      <div role="group" aria-label={`View of ${file.path}`} className="task-toggle">
        {markdown ? (
          <>
            <button type="button" className="button button-small" aria-pressed={view === 'rendered'} onClick={() => setView('rendered')}>Rendered</button>
            <button type="button" className="button button-small" aria-pressed={view === 'source'} onClick={() => setView('source')}>Source</button>
          </>
        ) : (
          <button type="button" className="button button-small" aria-expanded={view === 'source'} onClick={() => setView(previous => (previous === 'closed' ? 'source' : 'closed'))}>
            {view === 'closed' ? 'Show source' : 'Hide source'}
          </button>
        )}
      </div>
      {view !== 'closed' && state.status === 'loading' && <LoadingPanel>Loading {file.path}…</LoadingPanel>}
      {view !== 'closed' && state.status === 'error' && <ErrorPanel error={state.error} what={`The captured file ${file.path}`} onRetry={reload} />}
      {view !== 'closed' && state.status === 'ready' && (
        state.data.length === 0
          ? <p className="projects-muted">This file is empty.</p>
          : view === 'rendered'
            ? <div className="task-rendered" data-testid="file-rendered"><Markdown content={state.data} inert /></div>
            : <FileSource text={state.data} marked={marked} preRef={preRef} />
      )}
    </section>
  )
}

/**
 * "Files created or changed" on a launch node: every changed file of the result in order, captured ones with their content
 * and the findings that name them, the others with the reason they were not captured. A result recorded before capture
 * lists the paths and says the files were not captured.
 */
export function CreatedFiles({ scope, result, reviewNode, refreshToken, focusPath, onFocusApplied }: Props) {
  const captured = capturedFiles(result)
  const byPath = new Map(captured.map(file => [file.path, file]))
  const reasons = new Map(notCapturedFiles(result).map(entry => [entry.path, entry.reason]))
  const recorded = recordsCapture(result)
  // Every changed file in the result's order, then any captured or listed path the changed files do not name (never dropped).
  const listed = [...result.changed_files]
  for (const path of [...byPath.keys(), ...reasons.keys()]) if (!listed.includes(path)) listed.push(path)

  const reviewPath = captured.length === 0 ? null : reviewPathOf(scope, reviewNode)
  const loadReview = useCallback(
    (signal: AbortSignal) => orNotRecorded(fetchReviewResult(scope, reviewPath!, signal), NOT_RECORDED.review).then(review => review?.findings ?? null),
    [scope, reviewPath],
  )
  const { state: findings } = useResource(reviewPath === null ? null : `${reviewPath}|${reviewNode?.result_uri ?? reviewNode?.status}`, loadReview, refreshToken)

  // A file link is applied once: the target panel scrolls into view when it mounts, and the run view forgets the hand-over.
  const [focus] = useState(() => focusPath)
  useEffect(() => {
    if (focus !== null) onFocusApplied()
  }, [focus, onFocusApplied])

  return (
    <section className="evidence-section" aria-labelledby="evidence-created-files" data-testid="created-files" data-captured={captured.length}>
      <h4 id="evidence-created-files">Files created or changed</h4>
      {listed.length === 0 ? (
        <p className="projects-muted" data-testid="changed-files-empty">No changed files were recorded.</p>
      ) : (
        <>
          {!recorded && (
            <p className="projects-muted" data-testid="files-not-captured">
              Created files were not captured for this run (its results predate file capture), so only their paths are listed.
            </p>
          )}
          <ul className="evidence-list evidence-files" data-testid="changed-files">
            {listed.map(path => {
              const file = byPath.get(path)
              const reason = reasons.get(path)
              const state = file ? 'captured' : reason ? 'not-captured' : recorded ? 'unlisted' : 'not-recorded'
              return (
                <li key={path} data-testid="created-file" data-path={path} data-state={state} data-reason={reason}>
                  {file ? (
                    <CapturedFilePanel scope={scope} file={file} findings={findings} focused={focus === path} />
                  ) : (
                    <>
                      <code>{path}</code>
                      {reason && <span className="projects-muted" data-testid="not-captured-reason"> — {NOT_CAPTURED_WORDING[reason]}</span>}
                      {!reason && recorded && <span className="projects-muted"> — not captured, and no reason was recorded</span>}
                    </>
                  )}
                </li>
              )
            })}
          </ul>
          {focus !== null && !byPath.has(focus) && (
            <p className="projects-muted" data-testid="file-focus-missing">The linked file <code>{focus}</code> is not among this node's captured files.</p>
          )}
        </>
      )}
    </section>
  )
}
/**
 * The files a worker created or changed, as the trusted verifier captured them at freeze (PRD_VIEWER_CLARITY 4.1): every
 * changed text file within the caps is a `file` artifact carrying its repo-relative `path`; every other changed file is
 * listed in `files_not_captured` with the reason. Results recorded before capture carry neither. Pure helpers and one
 * hook, kept out of the component files so those only export components.
 */
import { useCallback } from 'react'
import { fetchWorkerResult, scopedResultPath, type RunDetail, type RunScope, type WorkerResult } from './api.ts'
import { useResource } from './useResource.ts'

type SnapshotNode = RunDetail['snapshot']['nodes'][number]
type Artifact = WorkerResult['artifacts'][number]
export type CapturedFile = Artifact & { kind: 'file'; path: string }
export type NotCapturedFile = NonNullable<WorkerResult['files_not_captured']>[number]

export const NOT_CAPTURED_WORDING: Record<NotCapturedFile['reason'], string> = {
  binary: 'binary file, not captured',
  too_large: 'too large to capture (over the per-file size cap)',
  missing: 'deleted or renamed away in the snapshot, nothing to capture',
  budget: "not captured: the packet's capture budget was already spent",
}

export function capturedFiles(result: WorkerResult): CapturedFile[] {
  return result.artifacts.filter((artifact): artifact is CapturedFile => artifact.kind === 'file' && typeof artifact.path === 'string')
}

export function notCapturedFiles(result: WorkerResult): NotCapturedFile[] {
  return result.files_not_captured ?? []
}

/** Whether the result records file capture at all; a result without either list predates it. */
export function recordsCapture(result: WorkerResult): boolean {
  return capturedFiles(result).length > 0 || result.files_not_captured !== undefined
}

export function isMarkdownPath(path: string): boolean {
  return /\.md$/i.test(path)
}

/** The element id of a captured file's panel on the launch node, the target of a finding's file link. */
export function fileAnchorId(path: string): string {
  return `file-${path.replace(/[^A-Za-z0-9_-]/g, '_')}`
}

/**
 * Every captured file of a run, by path, with the launch node that shows it. Read from the launch nodes' own served worker
 * results through the run's scoped results route; nothing is inferred for a lane whose result is absent or failed to load.
 */
export function useRunCapturedFiles(scope: RunScope, snapshotNodes: SnapshotNode[], refreshToken: number): Map<string, string> {
  const launches = snapshotNodes.flatMap(node => {
    if (node.kind !== 'worker' || node.result_uri === null) return []
    const path = scopedResultPath(scope, node.result_uri)
    return path === null ? [] : [{ nodeId: node.node_id, path }]
  })
  // The launches are serialised into the resource key, so the loader only changes when the linked results do.
  const spec = JSON.stringify(launches)
  const load = useCallback(async (signal: AbortSignal) => {
    const list = JSON.parse(spec) as typeof launches
    const settled = await Promise.allSettled(list.map(async launch => ({ nodeId: launch.nodeId, result: await fetchWorkerResult(scope, launch.path, signal) })))
    const byPath = new Map<string, string>()
    for (const entry of settled) {
      if (entry.status !== 'fulfilled') continue
      for (const file of capturedFiles(entry.value.result)) if (!byPath.has(file.path)) byPath.set(file.path, entry.value.nodeId)
    }
    return byPath
  }, [scope, spec])
  const key = launches.length === 0 ? null : `captured:${spec}`
  const { state } = useResource(key, load, refreshToken)
  return state.status === 'ready' ? state.data : EMPTY
}

const EMPTY: Map<string, string> = new Map()
/**
 * Scrolls a handed-over target (a highlighted task quote, a linked file) into view and keeps it there while the page
 * above it is still loading: results, files and Markdown arrive after the target mounts and would push it away. It stops
 * at the first sign of the reader moving (wheel, touch, key, pointer), after a quiet second without layout changes, or
 * after ten seconds.
 */
const QUIET_MS = 1000
const LIMIT_MS = 10_000
const READER_EVENTS = ['wheel', 'touchstart', 'keydown', 'pointerdown'] as const

export function keepInView(target: Element, options: ScrollIntoViewOptions): () => void {
  const view = target.ownerDocument.defaultView
  if (!view) return () => {}
  let quiet = 0
  const stop = () => {
    observer.disconnect()
    view.clearTimeout(quiet)
    view.clearTimeout(limit)
    for (const type of READER_EVENTS) view.removeEventListener(type, stop, true)
  }
  const scroll = () => {
    if (!target.isConnected) return stop()
    target.scrollIntoView(options)
    view.clearTimeout(quiet)
    quiet = view.setTimeout(stop, QUIET_MS)
  }
  // Content loading above the target grows one of its ancestors (the document itself may keep a fixed-height body).
  const observer = new ResizeObserver(scroll)
  for (let element = target.parentElement; element !== null; element = element.parentElement) observer.observe(element)
  const limit = view.setTimeout(stop, LIMIT_MS)
  for (const type of READER_EVENTS) view.addEventListener(type, stop, { capture: true, passive: true })
  scroll()
  return stop
}

import type { WorkerResult } from '../api.ts'
import { StatusBadge } from '../panels.tsx'

function shortSha(value: string | null): string {
  return value === null ? 'none' : value.slice(0, 12)
}

/**
 * The facts that anchor a result to its snapshot: status, attempt, session and commits. When a launch node and a verify
 * node link the same result they are shown once, on the verify node (docs/PRD_VIEWER_UX.md 7).
 */
export function ResultFacts({ result }: { result: WorkerResult }) {
  return (
    <dl className="projects-facts" data-testid="result-facts">
      <div><dt>Result status</dt><dd><StatusBadge status={result.status} /></dd></div>
      <div><dt>Attempt</dt><dd>{result.attempt}</dd></div>
      <div><dt>Session</dt><dd><code>{result.session_id}</code></dd></div>
      <div><dt>Base commit</dt><dd><code>{shortSha(result.base_commit)}</code></dd></div>
      <div><dt>Output commit</dt><dd>{result.output_commit ? <code>{shortSha(result.output_commit)}</code> : 'None recorded (no durable output commit)'}</dd></div>
    </dl>
  )
}

/** The error the result recorded: the gate's reasons on a verification, shown with the facts. */
export function ResultError({ result }: { result: WorkerResult }) {
  if (!result.error) return null
  return (
    <div className="projects-error" role="alert" data-testid="worker-error">
      <p><strong>Error {result.error.code}:</strong> {result.error.message}</p>
      <p>{result.error.retryable ? 'Marked retryable by the producer. Retrying is done through the workflow CLI, not this viewer.' : 'Marked not retryable by the producer.'}</p>
    </div>
  )
}

/**
 * The worker's narrative in its result: the summary and the open assumptions behind a count, absent when there are none. Shown
 * once, on the launch node, when it shares the result with its verify node.
 */
export function WorkerNarrative({ result }: { result: WorkerResult }) {
  return (
    <>
      <p className="worker-summary" data-testid="worker-summary">{result.summary}</p>
      {result.open_assumptions.length > 0 && (
        <details className="evidence-section assumptions-details" data-testid="assumptions-details">
          <summary id="evidence-assumptions">Open assumptions ({result.open_assumptions.length})</summary>
          <ul className="evidence-list" data-testid="assumptions">
            {result.open_assumptions.map((assumption, index) => <li key={index}>{assumption}</li>)}
          </ul>
        </details>
      )}
    </>
  )
}
/**
 * The run-scoped cache of immutable evidence (docs/PRD_VIEWER_UX.md 7): worker and candidate results (`results/<lane>/<k>`)
 * and recorded reviews (`reviews/<n>`) never change once served, so each URI is read once and kept for as long as the page
 * lives, shared by the run page's Now banner, the node pages and their attempt strips. Only the run detail, its events and
 * its inputs poll. A URI that answered 404 or failed is asked again when the caller's `stamp` changes: a Refresh, or new
 * events, after which a result that did not exist yet may.
 */
import { useCallback, useEffect, useMemo, useState, useSyncExternalStore } from 'react'
import {
  fetchReviewResult, fetchWorkerResult, NOT_RECORDED, orNotRecorded, ProjectsApiError, scopedResultPath, scopedReviewPath,
  type ReviewResult, type RunScope, type WorkerResult,
} from './api.ts'
import type { Resource } from './useResource.ts'

type Entry =
  | { status: 'ready'; value: unknown }
  /** A 404: not there (yet); asked again under another stamp. */
  | { status: 'absent'; error: unknown; stamp: string }
  | { status: 'failed'; error: unknown; stamp: string }

/** Enough for every attempt of a long run's steps; the oldest entries go first. */
const CACHE_LIMIT = 400
const cache = new Map<string, Entry>()
const inflight = new Set<string>()
const listeners = new Set<() => void>()
let version = 0

function settle(key: string, entry: Entry) {
  cache.delete(key)
  cache.set(key, entry)
  if (cache.size > CACHE_LIMIT) cache.delete(cache.keys().next().value!)
  version += 1
  listeners.forEach(listener => listener())
}

function subscribe(listener: () => void) {
  listeners.add(listener)
  return () => { listeners.delete(listener) }
}

type Fetcher = (uri: string) => Promise<unknown>

/** Fetches every URI the cache does not hold under this stamp; re-renders whenever any entry settles. */
function useCached(kind: 'result' | 'review', uris: readonly string[], stamp: string, fetcher: Fetcher): (uri: string) => Entry | undefined {
  const current = useSyncExternalStore(subscribe, () => version, () => version)
  const key = uris.join('\n')
  useEffect(() => {
    for (const uri of key === '' ? [] : key.split('\n')) {
      const cacheKey = `${kind}:${uri}`
      const known = cache.get(cacheKey)
      if (inflight.has(cacheKey) || (known && (known.status === 'ready' || known.stamp === stamp))) continue
      inflight.add(cacheKey)
      fetcher(uri).then(
        value => settle(cacheKey, { status: 'ready', value }),
        (error: unknown) => settle(cacheKey, error instanceof ProjectsApiError && error.notFound ? { status: 'absent', error, stamp } : { status: 'failed', error, stamp }),
      ).finally(() => inflight.delete(cacheKey))
    }
    // The fetcher is rebuilt per render; the scope it closes over is part of every URI.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [kind, key, stamp])
  // `current` re-reads the cache whenever an entry settles.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return useCallback((uri: string) => cache.get(`${kind}:${uri}`), [kind, current])
}

/** A result URI outside this run's results route is never fetched; it reads as absent. */
function resultFetcher(scope: RunScope): Fetcher {
  return uri => {
    const path = scopedResultPath(scope, uri)
    if (path === null) return Promise.reject(new ProjectsApiError('http', `The result link ${uri} is outside this run's results route.`, uri, { status: 404 }))
    return fetchWorkerResult(scope, path)
  }
}

/**
 * Several results at once: those that loaded, and how many were never answered yet. A result that answered 404 counts as
 * absent, not as loading; another failure counts as settled and is asked again under the next stamp.
 */
export function useRunResults(scope: RunScope, uris: readonly string[], stamp: string): { results: ReadonlyMap<string, WorkerResult>; pending: number } {
  const read = useCached('result', uris, stamp, resultFetcher(scope))
  const key = uris.join('\n')
  return useMemo(() => {
    const results = new Map<string, WorkerResult>()
    let pending = 0
    for (const uri of key === '' ? [] : key.split('\n')) {
      const entry = read(uri)
      if (entry?.status === 'ready') results.set(uri, entry.value as WorkerResult)
      else if (!entry) pending += 1
    }
    return { results, pending }
  }, [key, read])
}

/** A settled failure stays shown while a later stamp asks again, like a failed background reload. */
function asResource<T>(entry: Entry | undefined): Resource<T> {
  if (entry?.status === 'ready') return { status: 'ready', data: entry.value as T }
  if (entry) return { status: 'error', error: entry.error }
  return { status: 'loading' }
}

/** One result, as a resource: a node's own result, where a 404 is an error to show rather than an absence. `reload` asks again. */
export function useRunResult(scope: RunScope, uri: string | null, stamp: string): { state: Resource<WorkerResult>; reload: () => void } {
  const [retry, setRetry] = useState(0)
  const full = `${stamp}:${retry}`
  const read = useCached('result', uri === null ? [] : [uri], full, resultFetcher(scope))
  const reload = useCallback(() => setRetry(previous => previous + 1), [])
  return { state: uri === null ? { status: 'idle' } : asResource<WorkerResult>(read(uri)), reload }
}

/** The recorded review, read once per URI; a run whose export predates reviews has none (null). */
export function useRunReview(scope: RunScope, uri: string | null, stamp: string): Resource<ReviewResult | null> {
  const fetcher: Fetcher = reviewUri => {
    const path = scopedReviewPath(scope, reviewUri)
    if (path === null) return Promise.reject(new ProjectsApiError('http', `The review link ${reviewUri} is outside this run's reviews route.`, reviewUri, { status: 404 }))
    return orNotRecorded(fetchReviewResult(scope, path), NOT_RECORDED.review)
  }
  const read = useCached('review', uri === null ? [] : [uri], stamp, fetcher)
  return uri === null ? { status: 'idle' } : asResource<ReviewResult | null>(read(uri))
}
import { useEffect, useRef, useState } from 'react'
import { COMMAND_CAPTION, COMMAND_LEGEND, type NextStep, type RunbookRef } from '../../contracts/projects/triage.ts'

/** How long "Copied" stays beside a Copy button. */
const COPIED_MS = 2500

const runbookText = (ref: RunbookRef) => ref.topic ?? ref.section
const runbookTitle = (refs: RunbookRef[]) => refs.map(ref => `RUNBOOK › ${ref.section}${ref.topic ? ` › ${ref.topic}` : ''}`).join('\n')

/** Selects a command's text, so it can be copied by hand where the clipboard API is unavailable (a non-secure http origin). */
function select(element: HTMLElement) {
  const selection = element.ownerDocument.getSelection()
  if (!selection) return
  const range = element.ownerDocument.createRange()
  range.selectNodeContents(element)
  selection.removeAllRanges()
  selection.addRange(range)
}

/**
 * One copyable command (docs/PRD_VIEWER_UX.md 6.1): the command lives in a `<code>` outside any button, so the viewer offers
 * text to copy, never an action. Copy writes it to the clipboard, or selects it when the clipboard API is unavailable.
 */
function CommandLine({ text, caption }: { text: string; caption?: string }) {
  const code = useRef<HTMLElement>(null)
  const [outcome, setOutcome] = useState<'copied' | 'selected' | null>(null)
  useEffect(() => {
    if (outcome === null) return
    const timer = window.setTimeout(() => setOutcome(null), COPIED_MS)
    return () => window.clearTimeout(timer)
  }, [outcome])
  const copy = async () => {
    try {
      if (!window.isSecureContext || !navigator.clipboard) throw new Error('The clipboard is unavailable.')
      await navigator.clipboard.writeText(text)
      setOutcome('copied')
    } catch {
      if (code.current) select(code.current)
      setOutcome('selected')
    }
  }
  return (
    <div className="command-step-body">
      {caption && <span className="command-step-caption">{caption}</span>}
      <span className="command-line"><span className="command-prompt" aria-hidden="true">$ </span><code ref={code} data-testid="now-command">{text}</code></span>
      <button type="button" className="button button-small command-copy" data-testid="copy-command" aria-label="Copy command" onClick={() => void copy()}>Copy</button>
      <span className="command-copied" role="status">{outcome === 'copied' ? 'Copied' : outcome === 'selected' ? 'Selected: copy it with Ctrl+C' : ''}</span>
    </div>
