/* The section index sticks under the step strip once the page scrolls; its top is measured from the strip. */
.section-index { position: sticky; z-index: 2; display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: 4px 12px; margin: 8px 0 0; padding: 4px 0; background: var(--surface); border-bottom: 1px solid var(--border); }
