11:const MULTIPLE = 'multiple'
12:const LEGACY_MULTIPLE = 'both'
13:const NONE = 'none'
14:const UNRECORDED = 'unrecorded'
15:const SPECIAL_GROUPS: readonly string[] = [MULTIPLE, NONE, UNRECORDED]
16:const SPECIAL_LABEL: Record<string, string> = { [MULTIPLE]: 'Multiple workers', [NONE]: 'No worker (cross-cutting)', [UNRECORDED]: 'Worker not recorded' }
