18:/** The group a finding belongs to when grouped by worker: a lane id, `multiple` (also for legacy `both`), `none` or `unrecorded`. */
19:export function workerGroupOf(finding: Pick<ReviewFinding, 'worker'>): string {
20:  if (finding.worker === null) return UNRECORDED
21:  if (finding.worker === LEGACY_MULTIPLE) return MULTIPLE
22:  return finding.worker
23:}
24:
25:/** The Worker column wording: lane ids verbatim, the multi-lane values as words. */
26:export function workerWording(worker: string): string {
27:  if (worker === MULTIPLE || worker === LEGACY_MULTIPLE) return 'multiple workers'
28:  if (worker === NONE) return 'none'
29:  return worker
30:}
31:
32:/**
33: * The run's lanes in policy order: from the recorded inputs when loaded, else from the pinned graph's `launch_<id>`
34: * nodes (the naming the exporter guarantees), so findings group by lane even for a run whose inputs are not recorded.
35: */
36:export function runLanes(definitionNodes: DefinitionNode[], inputs: Resource<RunInputs | null>): string[] {
37:  if (inputs.status === 'ready' && inputs.data !== null) return inputs.data.workers.map(worker => worker.node_id)
38:  return definitionNodes.filter(node => node.kind === 'worker' && node.node_id.startsWith('launch_')).map(node => node.node_id.slice('launch_'.length))
39:}
40:
41:/**
42: * Worker groups in display order: the run's lanes, then any lane id a finding names that the run does not list
43: * (never dropped), then `multiple`, `none` and `unrecorded`. Only populated groups are rendered.
44: */
45:export function workerGroups(lanes: readonly string[], findings: readonly Pick<ReviewFinding, 'worker'>[]): { key: string; label: string }[] {
46:  const keys = [...lanes]
47:  for (const finding of findings) {
48:    const group = workerGroupOf(finding)
49:    if (!keys.includes(group) && !SPECIAL_GROUPS.includes(group)) keys.push(group)
50:  }
51:  return [...keys.map(lane => ({ key: lane, label: `Worker ${lane}` })), ...SPECIAL_GROUPS.map(key => ({ key, label: SPECIAL_LABEL[key] }))]
52:}
