54:/**
55: * Where a message names `path` verbatim: the index just past each occurrence. An occurrence counts only as a whole path, so
56: * `docs/a.md` is not named by `src/docs/a.md` or `docs/a.mdx`; a trailing sentence period or a `:N` line suffix still counts.
57: * Nothing is inferred from similar names or partial paths (PRD_VIEWER_CLARITY section 2).
58: */
59:function occurrencesOf(message: string, path: string): number[] {
60:  const ends: number[] = []
61:  if (path === '') return ends
62:  for (let index = message.indexOf(path); index !== -1; index = message.indexOf(path, index + 1)) {
63:    const before = index === 0 ? '' : message[index - 1]
64:    const end = index + path.length
65:    const after = message.slice(end, end + 2)
66:    if (/[\w./-]/.test(before)) continue
67:    if (/^[\w/-]/.test(after) || /^\.[\w/-]/.test(after)) continue
68:    ends.push(end)
69:  }
70:  return ends
71:}
72:
73:/** The findings whose message names `path` verbatim, in review order. */
74:export function findingsForFile<T extends Pick<ReviewFinding, 'message'>>(findings: readonly T[], path: string): T[] {
75:  return findings.filter(finding => occurrencesOf(finding.message, path).length > 0)
76:}
77:
78:/** The `[from, to]` line ranges a message names for `path`: one per `path:N` (N to N) or `path:N-M` occurrence. */
79:export function linesNamed(message: string, path: string): [number, number][] {
80:  const ranges: [number, number][] = []
81:  for (const end of occurrencesOf(message, path)) {
82:    const match = /^:(\d+)(?:[-–](\d+))?/.exec(message.slice(end))
83:    if (!match) continue
84:    const from = Number(match[1])
85:    const to = match[2] === undefined ? from : Number(match[2])
86:    if (from < 1) continue
87:    ranges.push([from, Math.max(from, to)])
88:  }
89:  return ranges
90:}

