  // The adapter links the launch node to the lane's latest worker packet, the one the verify node shows.
  const latest = Math.max(0, ...fixture.packets.filter(packet => packet.phase === 'worker').map(packet => packet.attempt))
  const launch = detail.snapshot.nodes.find(node => node.node_id === 'launch_ui')!
  if (launch.result_uri !== null) launch.result_uri = launch.result_uri.replace(/\/\d+$/, `/${latest}`)
  return detail
}

