const REVIEW: RawReviewSection = {
  attempt: 1, transport: 'native', reviewer_session_id: REVIEWER_SESSION, independent: true, bundle_sha256: '5d'.repeat(32), candidate_commit: CANDIDATE_COMMIT,
  verdict: 'approved',
