      ['09:28:21', 'freeze', 'succeeded', 'Immutable snapshots captured; worker-reported checks are not trusted'],
      ['09:28:21', 'verify_ui', 'running', `Attempt 1; revision ${OUTPUT_COMMIT_UI}`],
      ['09:29:28', 'verify_ui', 'blocked', VERIFY_FAILURE],
