      { phase: 'worker', attempt: 1, from: '09:28:25', to: '09:29:25', failure: VERIFY_FAILURE },
      { phase: 'worker', attempt: 2, from: '09:30:05', to: '09:31:05', failure: VERIFY_FAILURE },
      { phase: 'worker', attempt: 3, from: '09:35:15', to: '09:36:15' },
