/* ---- Run page (docs/PRD_VIEWER_UX.md 4.2-4.4, 10): header, Now banner, lanes, graph, Steps, Activity, step strip ---- */

/* Attention and warning tokens for both schemes: text 4.5:1 on its background, the amber ring 3:1 on the surface. */
:root {
  --warn-bg: #fff4d6;
  --warn-border: #c99a2e;
  --warn-text: #5c4100;
  --attention: #b86e00;
}
@media (prefers-color-scheme: dark) {
  :root {
    --warn-bg: #3a2f14;

  await expectNoExecutionControls(page)
})

test(`[scenario:output-first-task-collapsed] The launch node's result and files precede the task, the task disclosure is closed, and a finding's requirement link opens it and highlights the quote (${phase})`, async ({ page }, testInfo) => {
  await page.goto(clarityRunUrl(RUN_FILES, 'launch_ui'))
  const result = page.getByTestId('worker-result')
  await expect(result).toHaveAttribute('data-view', 'produced')
  await expect(createdFiles(page)).toBeVisible()
  const task = taskDetails(page)
  await expect(task).toBeVisible()

  // Output first: the result, then the files, the completion signal and the launch receipt, then the task.
  expect(await precedes(result, createdFiles(page))).toBe(true)
  expect(await precedes(createdFiles(page), page.getByTestId('worker-completion'))).toBe(true)
  expect(await precedes(page.getByTestId('worker-completion'), page.getByTestId('launch-receipt'))).toBe(true)
  expect(await precedes(page.getByTestId('launch-receipt'), task)).toBe(true)

  // The task is collapsed by default and appears once on the page.
  await expect(task).not.toHaveAttribute('open', '')
  await expect(page.getByTestId('task-panel')).toBeHidden()
  await expect(page.getByTestId('task-panel')).toHaveCount(1)
  await attach(page, testInfo, 'output-first-task-collapsed')

test(`[scenario:inert-markdown] Captured Markdown and decisions.md with a remote image and an external link make no network request, and the link renders as text (${phase})`, async ({ page }, testInfo) => {
  const remote = await recordRemoteRequests(page)

  // The captured Markdown file on the launch node.
  await page.goto(guardedRunUrl('launch_ui'))
  const file = page.locator(`[data-testid="captured-file"][data-path="${GUARDED_NOTES_PATH}"]`)
  const fileRendered = file.getByTestId('file-rendered')
  await expect(fileRendered.getByRole('heading', { level: 1, name: 'Guardrail notes' })).toBeVisible()
  await fileRendered.scrollIntoViewIfNeeded()
  await expectInert(fileRendered)
  // A bare URL is autolinked by GFM and just as inert; raw HTML stays literal text.
  await expect(fileRendered.locator(`[data-inert-link="${REMOTE_AUTOLINK_URL}"]`)).toBeVisible()
  await expect(fileRendered).toContainText(`<img src="${REMOTE_HTML_IMAGE_URL}" alt="pixel">`)
  await expect(nodeListItem(page, 'challenge')).toContainText('attempt 2')
  await expect(nodeListItem(page, 'review')).toContainText('attempt 1')

  await page.goto(guardedRunUrl('launch_ui'))
  const file = page.locator(`[data-testid="captured-file"][data-path="${GUARDED_NOTES_PATH}"]`)
  const listed = file.getByTestId('file-findings').getByTestId('file-finding')
  await expect(listed).toHaveCount(1)
  await expect(listed).toContainText(GUARDED_FILE_FINDING)
  await expect(listed).toHaveAttribute('data-reviewer', DEFAULT_REVIEWER_ID)
  await expect(file.getByTestId('file-findings-no-review')).toHaveCount(0)
  await expect(page.getByTestId('projects-error')).toHaveCount(0)
})
